//! Applies bounded builtin verification rules.

use crate::prelude::*;
impl Runtime {
    /// Verifies one quantifier-free premise generated by a builtin rule.
    /// A premise is a child proof obligation that must be verified before the rule may
    /// conclude its parent fact.
    ///
    /// Compound logical structure does not reset or consume the builtin-rule depth budget:
    /// conjunction and chains verify every atomic leaf, while disjunction first reuses the
    /// complete known `or` fact and otherwise verifies exactly one branch. Every atomic leaf
    /// returns to the bounded atomic premise verifier below.
    ///
    /// Example: list-set membership may use the single premise
    /// `a = 1 or a = 2 or a = 3` to prove `a $in {1, 2, 3}`.
    /// This compound entry is necessary because a known disjunction proves the complete `or`,
    /// not any selected equality; an atomic-only entry would discard exactly that evidence.
    pub fn verify_builtin_rule_premise(
        &mut self,
        premise: &QuantifierFreeFact,
        builtin_state: &BuiltinRuleSearchState,
    ) -> Result<StmtResult, RuntimeError> {
        match premise {
            QuantifierFreeFact::AtomicFact(atomic_fact) => {
                self.verify_atomic_fact_as_builtin_rule_premise(atomic_fact, builtin_state)
            }
            QuantifierFreeFact::AndFact(and_fact) => {
                self.verify_and_fact_as_builtin_rule_premise(and_fact, builtin_state)
            }
            QuantifierFreeFact::ChainFact(chain_fact) => {
                self.verify_chain_fact_as_builtin_rule_premise(chain_fact, builtin_state)
            }
            QuantifierFreeFact::OrFact(or_fact) => {
                self.verify_or_fact_as_builtin_rule_premise(or_fact, builtin_state)
            }
        }
    }

    /// Verifies a disjunction whose branches are atomic facts or flat conjunctions.
    /// Each inner vector is one sufficient alternative; it is not a list of independently
    /// known facts. This keeps rule implementations aligned with the `OrFact` AST shape.
    pub fn verify_builtin_rule_premise_alternatives(
        &mut self,
        alternatives: Vec<Vec<AtomicFact>>,
        line_file: LineFile,
        builtin_state: &BuiltinRuleSearchState,
    ) -> Result<StmtResult, RuntimeError> {
        let mut branches = Vec::with_capacity(alternatives.len());
        for mut alternative in alternatives {
            if alternative.is_empty() {
                return Ok(UnknownGenericStmtResult::new().into());
            }
            if alternative.len() == 1 {
                branches.push(alternative.remove(0).into());
            } else {
                branches.push(AndChainAtomicFact::AndFact(AndFact::new(
                    alternative,
                    line_file.clone(),
                )));
            }
        }
        self.verify_builtin_rule_premise(
            &QuantifierFreeFact::OrFact(OrFact::new(branches, line_file)),
            builtin_state,
        )
    }

    fn verify_and_fact_as_builtin_rule_premise(
        &mut self,
        and_fact: &AndFact,
        builtin_state: &BuiltinRuleSearchState,
    ) -> Result<StmtResult, RuntimeError> {
        if let Some(cached_result) =
            self.verify_fact_from_cache_using_display_string(&and_fact.clone().into())
        {
            return Ok(cached_result);
        }

        let mut child_results = Vec::with_capacity(and_fact.facts.len());
        for atomic_fact in &and_fact.facts {
            let result =
                self.verify_atomic_fact_as_builtin_rule_premise(atomic_fact, builtin_state)?;
            if !result.is_success() {
                return Ok(UnknownGenericStmtResult::new().into());
            }
            child_results.push(result);
        }
        Ok(SuccessFactStmtResult::new_with_verified_by_known_fact(
            and_fact.clone().into(),
            SuccessFactProofResult::combined_steps(Vec::new()),
            child_results,
        )
        .into())
    }

    fn verify_chain_fact_as_builtin_rule_premise(
        &mut self,
        chain_fact: &ChainFact,
        builtin_state: &BuiltinRuleSearchState,
    ) -> Result<StmtResult, RuntimeError> {
        if let Some(cached_result) =
            self.verify_fact_from_cache_using_display_string(&chain_fact.clone().into())
        {
            return Ok(cached_result);
        }

        let atomic_facts = chain_fact.facts()?;
        let mut child_results = Vec::with_capacity(atomic_facts.len());
        for atomic_fact in &atomic_facts {
            let result =
                self.verify_atomic_fact_as_builtin_rule_premise(atomic_fact, builtin_state)?;
            if !result.is_success() {
                return Ok(UnknownGenericStmtResult::new().into());
            }
            child_results.push(result);
        }
        Ok(SuccessFactStmtResult::new_with_verified_by_known_fact(
            chain_fact.clone().into(),
            SuccessFactProofResult::combined_steps(Vec::new()),
            child_results,
        )
        .into())
    }

    fn verify_and_chain_fact_as_builtin_rule_premise(
        &mut self,
        premise: &AndChainAtomicFact,
        builtin_state: &BuiltinRuleSearchState,
    ) -> Result<StmtResult, RuntimeError> {
        match premise {
            AndChainAtomicFact::AtomicFact(atomic_fact) => {
                self.verify_atomic_fact_as_builtin_rule_premise(atomic_fact, builtin_state)
            }
            AndChainAtomicFact::AndFact(and_fact) => {
                self.verify_and_fact_as_builtin_rule_premise(and_fact, builtin_state)
            }
            AndChainAtomicFact::ChainFact(chain_fact) => {
                self.verify_chain_fact_as_builtin_rule_premise(chain_fact, builtin_state)
            }
        }
    }

    fn verify_or_fact_as_builtin_rule_premise(
        &mut self,
        or_fact: &OrFact,
        builtin_state: &BuiltinRuleSearchState,
    ) -> Result<StmtResult, RuntimeError> {
        if let Some(cached_result) =
            self.verify_fact_from_cache_using_display_string(&or_fact.clone().into())
        {
            return Ok(cached_result);
        }
        let known_result = self.verify_or_fact_with_known_or_facts(or_fact)?;
        if known_result.is_success() {
            return Ok(known_result);
        }

        for (selected_index, branch) in or_fact.facts.iter().enumerate() {
            let branch_result =
                self.verify_and_chain_fact_as_builtin_rule_premise(branch, builtin_state)?;
            if !branch_result.is_success() {
                continue;
            }
            return Ok(
                SuccessFactStmtResult::new_with_verified_by_builtin_rule_evidence_recording_stmt(
                    or_fact.clone().into(),
                    "builtin premise: one disjunct verified".to_string(),
                    BuiltinRuleEvidence::DisjunctionIntroduction(
                        DisjunctionIntroductionBuiltinRuleEvidence::new(
                            or_fact.clone().into(),
                            branch.clone().into(),
                            selected_index,
                        ),
                    ),
                    vec![branch_result],
                )
                .into(),
            );
        }
        Ok(UnknownGenericStmtResult::new().into())
    }

    /// Atomic leaf fast path for rules whose premises are already atomic. Keeping this borrowed
    /// form avoids cloning every existing atomic premise merely to wrap it in
    /// [`QuantifierFreeFact::AtomicFact`]. Compound premises must use
    /// [`Runtime::verify_builtin_rule_premise`].
    pub fn verify_atomic_fact_as_builtin_rule_premise(
        &mut self,
        child: &AtomicFact,
        builtin_state: &BuiltinRuleSearchState,
    ) -> Result<StmtResult, RuntimeError> {
        match child {
            AtomicFact::EqualFact(equal_fact) => {
                let zero_premise_result =
                    self.verify_equal_fact_with_zero_premise_verification(equal_fact)?;
                if zero_premise_result.is_success() || !builtin_state.can_apply_rule() {
                    return Ok(zero_premise_result);
                }
                self.verify_equal_fact_with_one_premise_producing_builtin_rule(
                    equal_fact,
                    builtin_state,
                )
            }
            _ => {
                let zero_premise_result =
                    self.verify_non_equational_atomic_fact_with_zero_premise_verification(child)?;
                if zero_premise_result.is_success() || !builtin_state.can_apply_rule() {
                    return Ok(zero_premise_result);
                }
                self.verify_non_equational_atomic_fact_with_one_premise_producing_builtin_rule(
                    child,
                    builtin_state,
                )
            }
        }
    }

    pub fn verify_builtin_rule_premises(
        &mut self,
        children: &[AtomicFact],
        builtin_state: &BuiltinRuleSearchState,
    ) -> Result<Option<Vec<StmtResult>>, RuntimeError> {
        match children {
            [] => Ok(Some(Vec::new())),
            [child] => {
                let result =
                    self.verify_atomic_fact_as_builtin_rule_premise(child, builtin_state)?;
                Ok(result.is_success().then_some(vec![result]))
            }
            _ => {
                // Jointly required atomic premises form one conjunction. Trying the complete
                // `AndFact` lets a stored whole conjunction satisfy the rule; otherwise the
                // compound dispatcher verifies every leaf with the unchanged depth budget.
                let conjunction = QuantifierFreeFact::AndFact(AndFact::new(
                    children.to_vec(),
                    children[0].line_file(),
                ));
                let result = self.verify_builtin_rule_premise(&conjunction, builtin_state)?;
                Ok(result.is_success().then_some(vec![result]))
            }
        }
    }
}

